le\": \"Fourier transform\",\n    \"description\": \"Compare a signal with its frequency-domain representation.\",\n    \"principle\": \"Frequency-domain structure describes a signal’s component frequencies\",\n    \"concept\": \"fourier\",\n    \"aliases\": [\n      \"fourier transform\",\n      \"fourier transform\"\n    ],\n    \"parameters\": [\n      {\n        \"key\": \"a\",\n        \"label\": \"a\",\n        \"unit\": \"\",\n        \"min\": 0.2,\n        \"max\": 3,\n        \"default\": 1\n      }\n    ],\n    \"modes\": [],\n    \"protected\": true\n  },\n  {\n    \"id\": \"minitab-gamma-function\",\n    \"route\": \"/minitab/gamma-function\",\n    \"subject\": \"Mathematics\",\n    \"title\": \"Gamma function\",\n    \"description\": \"Explore how the gamma function extends factorials beyond positive integers.\",\n    \"principle\": \"Γ(n) = (n−1)! for positive integers n\",\n    \"concept\": \"special\",\n    \"aliases\": [\n      \"gamma function\",\n      \"gamma function\"\n    ],\n    \"parameters\": [],\n    \"modes\": [],\n    \"protected\": true\n  },\n  {\n    \"id\": \"minitab-gradient-explorer\",\n    \"route\": \"/minitab/gradient-explorer\",\n    \"subject\": \"Mathematics\",\n    \"title\": \"Gradient explorer\",\n    \"description\": \"Explore how a scalar field changes and how its gradient points uphill.\",\n    \"principle\": \"∇f points in the direction of greatest local increase\",\n    \"concept\": \"calculus\",\n    \"aliases\": [\n      \"gradient explorer\",\n      \"gradient explorer\"\n    ],\n    \"parameters\": [],\n    \"modes\": [],\n    \"protected\": true\n  },\n  {\n    \"id\": \"minitab-hermite-laguerre-delta\",\n    \"route\": \"/minitab/hermite-laguerre-delta\",\n    \"subject\": \"Mathematics\",\n    \"title\": \"Hermite, Laguerre and delta\",\n    \"description\": \"Explore special functions and finite-width representations of a delta distribution.\",\n    \"principle\": \"A delta distribution is defined through its action under integration\",\n    \"concept\": \"special\",\n    \"aliases\": [\n      \"hermite laguerre delta\",\n      \"hermite, laguerre and delta\"\n    ],\n    \"parameters\": [\n      {\n        \"key\": \"epsExp\",\n        \"label\": \"epsExp\",\n        \"unit\": \"\",\n        \"min\": -2,\n        \"max\": 0.3,\n        \"default\": 0\n      }\n    ],\n    \"modes\": [],\n    \"protected\": true\n  },\n  {\n    \"id\": \"minitab-legendre-bessel\",\n    \"route\": \"/minitab/legendre-bessel\",\n    \"subject\": \"Mathematics\",\n    \"title\": \"Legendre and Bessel functions\",\n    \"description\": \"Explore special-function solutions that arise in problems with symmetry.\",\n    \"principle\": \"Boundary conditions select physically relevant solutions\",\n    \"concept\": \"special\",\n    \"aliases\": [\n      \"legendre bessel\",\n      \"legendre and bessel functions\"\n    ],\n    \"parameters\": [\n      {\n        \"key\": \"besX\",\n        \"label\": \"besX\",\n        \"unit\": \"\",\n        \"min\": 0.5,\n        \"max\": 14.5,\n        \"default\": 5\n      }\n    ],\n    \"modes\": [],\n    \"protected\": true\n  }\n]\n", "src/lib/explorer/catalog.ts": "import data from './topics-data.json';\nexport type Language = 'en' | 'yo' | 'ha' | 'ig';\nexport type Parameter = { key: string; label: string; unit: string; min: number; max: number; default: number; integer?:boolean };\nexport type Topic = { id: string; route: string; subject: string; title: string; description: string; principle: string; concept: string; aliases: string[]; parameters: Parameter[]; modes: { key: string; default: string; options: string[] }[]; protected: boolean };\nexport const topics: Topic[] = data;\nexport function getTopic(id: string) { return topics.find(t => t.id === id); }\nexport function isLanguage(value: unknown): value is Language { return ['en','yo','ha','ig'].includes(value as string); }\nexport function normalize(text: string) { return text.normalize('NFD').replace(/[\\u0300-\\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); }\n", "src/lib/explorer/prepare.ts": "import { getTopic, isLanguage, normalize, topics, type Language, type Topic } from './catalog';\nimport { conceptExplanation, ui } from './locales';\nexport class ExplorerError extends Error { constructor(message:string, public status=422) { super(message); } }\nexport type ExplorerResult = { topicId:string; title:string; route:string; language:Language; params:Record<string,number>; modes:Record<string,string>; requested:string[]; explanation:string; calculation:string|null; url:string; mode:'demo' };\nconst aliasOverrides: Record<string,Record<string,string[]>> = {\n 'mathematics-unit-circle': {angleDeg:['angle']},\n 'simulations-ohms-law': {V:['voltage','supply voltage'],r1:['resistance','r','resistor']},\n 'simulations-newtons-laws': {mass2:['mass'],applied:['force','applied force'],friction2:['friction','mu']},\n 'simulations-projectile-motion': {v0:['speed','velocity','initial speed','initial velocity'],angle:['launch angle','igun','kusurwa','nkuku'],g:['gravity'],h0:['height']},\n 'simulations-waves': {f:['frequency'],lambda:['wavelength'],A:['amplitude']},\n 'simulations-radioactive-decay': {n0:['initial population'],halfLife:['half life']},\n};\nconst units:Record<string,Record<string,string>>={\n 'mathematics-unit-circle':{angleDeg:'°|degrees?'},\n 'simulations-ohms-law':{V:'V',r1:'Ω|ohms?'},'simulations-newtons-laws':{mass2:'kg',applied:'N'},\n 'simulations-projectile-motion':{g:'m/s²|m/s\\\\^2',v0:'m/s',angle:'°|degrees?'},\n 'simulations-waves':{f:'Hz',lambda:'m'},'simulations-polarization':{polarizerAngle:'°|degrees?'},\n};\nfunction escape(s:string) { return s.replace(/[.*+?^${}()|[\\]\\\\]/g,'\\\\$&'); }\nexport function detectTopic(prompt:string):Topic|undefined {\n const s=' '+normalize(prompt)+' ';\n const matches=topics.flatMap(topic=>topic.aliases.filter(a=>s.includes(' '+normalize(a)+' ')).map(a=>({topic,score:normalize(a).length})));\n matches.sort((a,b)=>b.score-a.score);\n return matches[0]?.topic;\n}\nexport function validateSettings(topic:Topic, raw:unknown, rawModes:unknown) {\n const params:Record<string,number>={}, modes:Record<string,string>={};\n if(!raw || typeof raw!=='object' || Array.isArray(raw)) throw new ExplorerError('Invalid settings.');\n for(const [key,value] of Object.entries(raw)) {const p=topic.parameters.find(p=>p.key===key);if(!p||typeof value!=='number'||!Number.isFinite(value)||value<p.min||value>p.max||(p.integer&&!Number.isInteger(value)))throw new ExplorerError(`${key}: ${p?`${p.min}–${p.max} ${p.unit}`:'unsupported parameter'}`);params[key]=value;}\n if(!rawModes||typeof rawModes!=='object'||Array.isArray(rawModes))throw new ExplorerError('Invalid mode.');\n for(const [key,value] of Object.entries(rawModes)) {const m=topic.modes.find(m=>m.key===key);if(!m||typeof value!=='string'||!m.options.includes(value))throw new ExplorerError('Unsupported mode: '+key);modes[key]=value;}\n return {params,modes};\n}\nexport function calculate(topic:Topic,p:Record<string,number>,m:Record<string,string>):string|null {\n const n=(x:number)=>Number(x.toPrecision(5));\n if(topic.id==='mathematics-unit-circle'){const r=p.angleDeg*Math.PI/180;return `sin ${p.angleDeg}° = ${n(Math.sin(r))}; cos ${p.angleDeg}° = ${n(Math.cos(r))}. Angle measured anticlockwise from positive x-axis.`;}\n if(topic.id==='simulations-ohms-law') {const R=m.mode==='series'?p.r1+p.r2+p.r3:m.mode==='parallel'?1/(1/p.r1+1/p.r2+1/p.r3):p.r1;if(m.mode==='non-ohmic')return null;return `I = V/R = ${p.V}/${n(R)} = ${n(p.V/R)} A; P = VI = ${n(p.V*p.V/R)} W. Ohmic resistors at fixed physical conditions.`;}\n if(topic.id==='simulations-newtons-laws'&&m.law==='2nd') {const friction=p.friction2*p.mass2*9.81;return `a = max(0, F − μmg)/m = ${n(Math.max(0,p.applied-friction)/p.mass2)} m/s². Block initially at rest on a horizontal surface; g = 9.81 m/s²; simplified friction model.`;}\n if(topic.id==='simulations-waves'&&m.mode!=='standing'&&m.mode!=='superposition')return `v = fλ = ${p.f} × ${p.lambda} = ${n(p.f*p.lambda)} m/s; T = 1/f = ${n(1/p.f)} s.`;\n if(topic.id==='simulations-projectile-motion'&&m.mode==='standard'){const r=p.angle*Math.PI/180,vy=p.v0*Math.sin(r),time=(vy+Math.sqrt(vy*vy+2*p.g*p.h0))/p.g;return `T = ${n(time)} s; horizontal range = ${n(p.v0*Math.cos(r)*time)} m. Standard launch from h₀ = ${p.h0} m; no air resistance; landing at y = 0.`;}\n return null;\n}\nexport function prepare(input:{prompt?:unknown;topicId?:unknown;language?:unknown;params?:unknown;modes?:unknown}):ExplorerResult {\n const language=isLanguage(input.language)?input.language:'en';\n if(input.language!==undefined&&!isLanguage(input.language))throw new ExplorerError('Unsupported language.',400);\n if(input.prompt!==undefined&&typeof input.prompt!=='string')throw new ExplorerError('Invalid prompt.',400);\n const prompt=typeof input.prompt==='string'?input.prompt.trim():'';\n if(prompt.length>1200)throw new ExplorerError('Prompt too long.',400);\n const topic=typeof input.topicId==='string'&&input.topicId?getTopic(input.topicId):detectTopic(prompt);\n if(!topic)throw new ExplorerError(ui[language].noMatch);\n const params:Record<string,number>=Object.fromEntries(topic.parameters.map(p=>[p.key,p.default]));\n const modes:Record<string,string>=Object.fromEntries(topic.modes.map(m=>[m.key,m.default]));\n const provided=validateSettings(topic,input.params??{},input.modes??{});Object.assign(params,provided.params);Object.assign(modes,provided.modes);\n if(topic.id==='simulations-newtons-laws'&&!provided.modes.law) {\n  if (/\\b(first|1st)\\b/i.test(prompt)) modes.law='1st';\n  else if (/\\b(third|3rd)\\b/i.test(prompt)) modes.law='3rd';\n  else if (/\\b(second|2nd)\\b/i.test(prompt)||/\\d/.test(prompt)) modes.law='2nd';\n }\n for(const mode of topic.modes) {\n  const pattern=new RegExp('(?:^|[\\\\s,;])'+escape(mode.key)+'\\\\s*=\\\\s*([a-z0-9-]+)','gi');\n  const explicit=[...prompt.matchAll(pattern)];\n  if(explicit.length>1||(explicit.length&&provided.modes[mode.key]))throw new ExplorerError('Repeated mode: '+mode.key);\n  if(explicit.length){const value=explicit[0][1];if(!mode.options.includes(value))throw new ExplorerError('Unsupported mode: '+value);modes[mode.key]=value;}\n  else if(!provided.modes[mode.key]) {const text=' '+normalize(prompt)+' ';const matches=mode.options.filter(value=>text.includes(' '+normalize(value)+' '));if(matches.length===1)modes[mode.key]=matches[0];}\n }\n const effectiveLaw=typeof provided.modes.law==='string'?provided.modes.law:(/law\\s*=\\s*(1st|2nd|3rd)/i.exec(prompt)?.[1]||modes.law);\n const newtonAliases=effectiveLaw==='1st'?{mass1:['mass'],force1:['force'],friction1:['friction','mu']}:effectiveLaw==='3rd'?{mass3a:['mass'],force3:['force']}:aliasOverrides[topic.id];\n const aliases=topic.id==='simulations-newtons-laws'?newtonAliases:(topic.id==='simulations-projectile-motion'&&modes.mode!=='standard'?{}:aliasOverrides[topic.id]);\n const unitMap=topic.id==='simulations-projectile-motion'&&modes.mode!=='standard'?{}:topic.id==='simulations-newtons-laws'?(effectiveLaw==='1st'?{mass1:'kg',force1:'N'}:effectiveLaw==='3rd'?{mass3a:'kg',force3:'N'}:units[topic.id]):units[topic.id];\nconst requested=new Set(Object.keys(provided.params));\n let remaining=prompt.normalize('NFC');\n const number='([-+]?(?:\\\\d+(?:\\\\.\\\\d*)?|\\\\.\\\\d+)(?:e[-+]?\\\\d+)?)';\n // Exact key=value assignments work for every registered numeric control.\n for(const p of [...topic.parameters].sort((a,b)=>b.key.length-a.key.length)) {\n  const names=[p.key,...((aliases as Record<string,string[]>|undefined)?.[p.key]||[])];\n  const expression=new RegExp('(?:^|[\\\\s,;])(?:'+names.map(escape).join('|')+')\\\\s*(?:=|:)\\\\s*'+number+'(?![\\\\d.])','gi');\n  remaining=remaining.replace(expression,(whole,value:string)=>{if(requested.has(p.key))throw new ExplorerError('Repeated setting: '+p.key);const checked=validateSettings(topic,{[p.key]:Number(value)},{});params[p.key]=checked.params[p.key];requested.add(p.key);return ' '.repeat(whole.length);});\n }\n for(const mode of topic.modes){const expr=new RegExp('(?:^|[\\\\s,;])'+escape(mode.key)+'\\\\s*=\\\\s*([a-z0-9-]+)','gi');remaining=remaining.replace(expr,(whole,value:string)=>{if(!mode.options.includes(value))throw new ExplorerError('Unsupported mode: '+value);modes[mode.key]=value;return ' '.repeat(whole.length);});}\n for(const [key,unit] of Object.entries(unitMap||{})) {\n  const expr=new RegExp('(?<![a-z0-9.])'+number+'\\\\s*(?:'+unit+')(?![a-z0-9²^])','gi');\n  remaining=remaining.replace(expr,(whole,value:string)=>{if(requested.has(key))throw new ExplorerError('Repeated setting: '+key);const checked=validateSettings(topic,{[key]:Number(value)},{});params[key]=checked.params[key];requested.add(key);return ' '.repeat(whole.length);});\n }\n // Remove topic identifiers before detecting unparsed numbers in scientific names.\n for(const alias of [...topic.aliases,topic.id].sort((a,b)=>b.length-a.length))remaining=remaining.replace(new RegExp(escape(alias),'gi'),' ');\n if(topic.id==='simulations-newtons-laws')remaining=remaining.replace(/\\b(first|second|third|1st|2nd|3rd)\\b/gi,' ');\n if(/\\d/.test(remaining))throw new ExplorerError(ui[language].invalid);\n\n const query=new URLSearchParams({afTopic:topic.id,afLang:language,afParams:JSON.stringify(params),afModes:JSON.stringify(modes)});\n return {topicId:topic.id,title:topic.title,route:topic.route,language,params,modes,requested:[...requested],explanation:conceptExplanation(topic.concept,language,topic.description),calculation:calculate(topic,params,modes),url:topic.route+'?'+query.toString(),mode:'demo'};\n}\nexport function presetFromSearch(id:string,search:string) {\n const topic=getTopic(id);if(!topic)return null;const q=new URLSearchParams(search);if(q.get('afTopic')!==id)return null;\n try {const raw=q.get('afParams')||'{}',m=q.get('afModes')||'{}';if(raw.length>12000||m.length>2000)return null;return validateSettings(topic,JSON.parse(raw),JSON.parse(m));}catch{return null;}\n}\n", "src/components/explorer/ResultCard.tsx": "'use client';\nimport { getTopic, topics } from '@/lib/explorer/catalog';\nimport { ui } from '@/lib/explorer/locales';\nimport type { ExplorerResult } from '@/lib/explorer/prepare';\nexport function ResultCard({result,showOpen=true}:{result:ExplorerResult;showOpen?:boolean}) {\n const topic=getTopic(result.topicId);if(!topic)return null;const s=ui[result.language];\n return <article lang={result.language} className=\"mt-4 rounded-2xl border border-indigo-200 bg-white p-5 text-gray-900 shadow-sm\">\n  <p className=\"text-xs font-semibold text-indigo-700\">{s.free}</p><h2 className=\"mt-2 text-xl font-semibold\">{topic.title}</h2><p className=\"mt-3 text-sm leading-7\">{result.explanation}</p>\n  <div className=\"mt-4 rounded-xl bg-indigo-50 p-4\"><h3 className=\"text-xs font-semibold text-indigo-900\">{s.principle}</h3><p className=\"mt-2 text-sm leading-7 text-indigo-950\">{topic.principle}</p></div>\n  {result.calculation&&<div className=\"mt-3 rounded-xl bg-emerald-50 p-4\"><h3 className=\"text-xs font-semibold text-emerald-900\">{s.numerical}</h3><p className=\"mt-2 text-sm leading-7 text-emerald-950\">{result.calculation}</p><p className=\"mt-2 text-xs text-emerald-900\">Formulae, units and calculation assumptions: English.</p></div>}\n  {result.language!=='en'&&<details className=\"mt-3 text-sm\"><summary className=\"cursor-pointer text-indigo-800\">{s.source}</summary><p className=\"mt-2 leading-7\">{topic.description}</p></details>}\n  {!!topic.parameters.length&&<details className=\"mt-4 text-sm\"><summary className=\"cursor-pointer font-medium\">{s.settings} ({topic.parameters.length})</summary><p className=\"my-2 text-xs leading-6 text-gray-700\">{s.omitted} {s.bridge}</p><div className=\"overflow-x-auto\"><table className=\"w-full text-left text-xs\"><thead><tr className=\"border-b\"><th className=\"p-2\">Key</th><th className=\"p-2\">Value</th><th className=\"p-2\">Range</th></tr></thead><tbody>{topic.parameters.map(p=><tr className=\"border-b border-gray-100\" key={p.key}><td className=\"p-2\">{p.label} <code>({p.key})</code></td><td className=\"p-2\">{result.params[p.key]} {p.unit}{result.requested.includes(p.key)?' *':''}</td><td className=\"p-2\">{p.min}–{p.max}</td></tr>)}</tbody></table></div></details>}\n  {Object.keys(result.modes).length>0&&<p className=\"mt-3 text-xs text-gray-700\">{s.modes}: {Object.entries(result.modes).map(([k,v])=>`${k}=${v}`).join(', ')}</p>}\n  <p className=\"mt-3 text-xs leading-6 text-gray-700\">{s.manual} {s.limitations}</p>{topic.protected&&<p className=\"mt-2 text-xs font-medium text-amber-900\">{s.protected}</p>}\n  {showOpen&&<a href={result.url} className=\"mt-4 inline-block rounded-xl bg-indigo-700 px-5 py-3 text-sm font-semibold text-white hover:bg-indigo-800\">{s.open} →</a>}\n  <details className=\"mt-4 text-xs\"><summary className=\"cursor-pointer text-gray-700\">{s.reference}</summary><div className=\"mt-2 flex flex-wrap gap-3\">{topics.filter(t=>t.id!==topic.id&&t.concept===topic.concept).slice(0,4).map(t=><a className=\"text-indigo-800 underline\" key={t.id} href={'/explore?topic='+encodeURIComponent(t.id)+'&lang='+result.language}>{t.title}</a>)}</div></details>\n </article>;\n}\n", "src/components/explorer/TopicContext.tsx": "'use client';\nimport { useEffect, useState } from 'react';\nimport { usePathname } from 'next/navigation';\nimport { topics, isLanguage, type Language } from '@/lib/explorer/catalog';\nimport { prepare, presetFromSearch, type ExplorerResult } from '@/lib/explorer/prepare';\nimport { languageNames, ui } from '@/lib/explorer/locales';\nimport { ResultCard } from './ResultCard';\nexport function TopicContext(){\n const pathname=usePathname();\n const [result,setResult]=useState<ExplorerResult|null>(null),[open,setOpen]=useState(false);\n useEffect(()=>{setResult(null);setOpen(false);const topic=topics.find(t=>t.route===pathname);if(!topic)return;const q=new URLSearchParams(window.location.search);let language:Language='en';try{const l=q.get('afLang')||localStorage.getItem('afactor-simulation-language-v1');if(isLanguage(l))language=l;}catch{}\n const preset=presetFromSearch(topic.id,window.location.search);try{setResult(prepare({topicId:topic.id,language,params:preset?.params||{},modes:preset?.modes||{}}));setOpen(!!preset);}catch{}\n },[pathname]);\n if(!result||result.route!==pathname)return null;const s=ui[result.language];\n return <section className=\"border-b border-indigo-200 bg-slate-100 px-4 py-3 text-gray-900\" style={{colorScheme:'light'}}><div className=\"mx-auto max-w-6xl\"><div className=\"flex flex-wrap items-center justify-between gap-3\"><button onClick={()=>setOpen(v=>!v)} className=\"text-sm font-semibold text-indigo-900\">{open?s.close:s.principle} · {result.title}</button><div className=\"flex items-center gap-3\"><select aria-label={s.language} value={result.language} onChange={e=>{const language=e.target.value as Language;setResult(prepare({topicId:result.topicId,language,params:result.params,modes:result.modes}));}} className=\"rounded-lg border border-gray-300 bg-white px-2 py-1 text-xs\">{Object.entries(languageNames).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select><a href={'/explore?topic='+encodeURIComponent(result.topicId)+'&lang='+result.language} className=\"text-xs text-indigo-900 underline\">{s.review}</a></div></div>{open&&<ResultCard result={result} showOpen={false}/>}</div></section>;\n}\n", "src/app/explore/page.tsx": "import { AppHeader } from '@/components/layout/AppHeader';\nimport { PromptBar } from '@/components/ai/PromptBar';\nimport { topics } from '@/lib/explorer/catalog';\nexport const metadata={title:'Topic explorer | A-Factor STEM Studio'};\nexport default function ExplorePage(){return <div style={{background:'#f1f5f9',minHeight:'100vh',color:'#111827',colorScheme:'light'}}><AppHeader/><main className=\"mx-auto max-w-6xl px-4 py-10 sm:px-6\"><p className=\"text-xs font-semibold uppercase tracking-widest text-indigo-700\">A-Factor STEM Studio</p><h1 className=\"mt-2 text-3xl font-semibold\">Explore all {topics.length} topics</h1><p className=\"mb-7 mt-3 max-w-2xl text-sm leading-7 text-gray-700\">Physics, Chemistry, Mathematics and Geophysics. Select an existing activity, prepare supported controls, and read a topic-specific explanation without a paid AI API.</p><PromptBar/></main></div>;}\n", "src/app/api/ai/route.ts": "import { NextRequest, NextResponse } from 'next/server';\nimport { ExplorerError, prepare } from '@/lib/explorer/prepare';\nexport async function POST(req:NextRequest) {\n let body:unknown;\n try {const raw=await req.text();if(raw.length>16000)return NextResponse.json({error:'Request too large.'},{status:413});body=JSON.parse(raw);}catch{return NextResponse.json({error:'Invalid JSON.'},{status:400});}\n if(!body||typeof body!=='object'||Array.isArray(body))return NextResponse.json({error:'Invalid request.'},{status:400});\n try {return NextResponse.json(prepare(body),{headers:{'Cache-Control':'no-store'}});}catch(error){return NextResponse.json({error:error instanceof ExplorerError?error.message:'Unable to prepare this activity.'},{status:error instanceof ExplorerError?error.status:500});}\n}\n", "src/components/ai/PromptBar.tsx": "'use client';\nimport { useEffect, useRef, useState } from 'react';\nimport type { AIPromptResponse } from '@/types/ai';\nimport { getTopic, isLanguage, topics, type Language } from '@/lib/explorer/catalog';\nimport { languageNames, ui } from '@/lib/explorer/locales';\nimport type { ExplorerResult } from '@/lib/explorer/prepare';\nimport { ResultCard } from '@/components/explorer/ResultCard';\ninterface Props { onResult?:(result:AIPromptResponse)=>void; className?:string; }\nexport function PromptBar({onResult,className}:Props) {\n const [language,setLanguage]=useState<Language>('en'),[topicId,setTopicId]=useState(''),[prompt,setPrompt]=useState('');\n const [numbers,setNumbers]=useState<Record<string,string>>({}),[modes,setModes]=useState<Record<string,string>>({});\n const [result,setResult]=useState<ExplorerResult|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false);\n const pending=useRef<AbortController|null>(null);const s=ui[language],topic=getTopic(topicId);\n useEffect(()=>{const q=new URLSearchParams(window.location.search),id=q.get('topic'),lang=q.get('lang');if(id&&getTopic(id))setTopicId(id);try{const saved=lang||localStorage.getItem('afactor-simulation-language-v1');if(isLanguage(saved))setLanguage(saved);}catch{}return()=>pending.current?.abort();},[]);\n function reset(){pending.current?.abort();pending.current=null;setBusy(false);setError('');setResult(null);}\n function changeTopic(id:string){reset();setTopicId(id);setNumbers({});setModes({});}\n function changeLanguage(value:Language){reset();setLanguage(value);try{localStorage.setItem('afactor-simulation-language-v1',value);}catch{}}\n async function submit(text=prompt){if(busy||(!text.trim()&&!topicId))return;const controller=new AbortController();pending.current=controller;setBusy(true);setError('');setResult(null);const timer=setTimeout(()=>controller.abort(),15000);\n try {const params:Record<string,number>={};for(const [k,v] of Object.entries(numbers))if(v.trim())params[k]=Number(v);const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({prompt:text,topicId:topicId||undefined,language,params,modes})});const data=await r.json();if(!r.ok)throw Error(data.error||s.error);if(pending.current!==controller)return;setResult(data);\n // Preserve the homepage's existing projectile preview for the compatible standard case.\n if(onResult&&window.location.pathname==='/'&&data.topicId==='simulations-projectile-motion'&&data.modes.mode==='standard'&&data.params.h0===0)onResult({simulationType:'projectile_motion',title:data.title,description:data.explanation,explanation:data.explanation,params:{initialVelocity:data.params.v0,angle:data.params.angle,gravity:data.params.g,mass:1},suggestedFollowUps:[]});\n }catch(e){if(pending.current===controller)setError(e instanceof Error?e.message:s.error);}finally{clearTimeout(timer);if(pending.current===controller){pending.current=null;setBusy(false);}}}\n const sample=topic?`${topic.title}${topic.parameters.length?' '+topic.parameters[0].key+'='+topic.parameters[0].default:''}`:'';\n return <div className={className} style={{colorScheme:'light'}}><div className=\"grid gap-3 sm:grid-cols-[1fr_180px]\">\n  <label className=\"text-xs font-semibold text-gray-800\">{s.topic}<select value={topicId} onChange={e=>changeTopic(e.target.value)} className=\"mt-1 w-full rounded-xl border border-gray-300 bg-white p-3 text-sm text-gray-900\"><option value=\"\">{s.automatic}</option>{['Physics','Chemistry','Mathematics','Geophysics'].map(subject=><optgroup label={subject} key={subject}>{topics.filter(t=>t.subject===subject).map(t=><option key={t.id} value={t.id}>{t.title}</option>)}</optgroup>)}</select></label>\n  <label className=\"text-xs font-semibold text-gray-800\">{s.language}<select value={language} onChange={e=>changeLanguage(e.target.value as Language)} className=\"mt-1 w-full rounded-xl border border-gray-300 bg-white p-3 text-sm text-gray-900\">{Object.entries(languageNames).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label>\n </div><p className=\"my-3 text-xs leading-6 text-emerald-900\">{s.free}</p><form onSubmit={e=>{e.preventDefault();void submit();}} className=\"flex flex-col gap-2 sm:flex-row\"><label className=\"sr-only\" htmlFor=\"all-topic-prompt\">{s.prompt}</label><input id=\"all-topic-prompt\" value={prompt} maxLength={1200} onChange={e=>setPrompt(e.target.value)} placeholder={s.prompt} className=\"min-w-0 flex-1 rounded-xl border border-gray-300 bg-white px-4 py-3 text-sm text-gray-900 placeholder:text-gray-600\" /><button disabled={busy||(!prompt.trim()&&!topicId)} className=\"rounded-xl bg-indigo-700 px-5 py-3 text-sm font-semibold text-white disabled:opacity-50\">{busy?'…':s.apply}</button></form>\n {topic&&<details className=\"mt-3 rounded-xl border border-gray-200 bg-white p-4\"><summary className=\"cursor-pointer text-sm font-medium text-gray-800\">{s.settings} · {topic.parameters.length}</summary><p className=\"my-3 text-xs leading-6 text-gray-700\">{s.omitted} {s.manual}</p><div className=\"grid gap-3 sm:grid-cols-2 lg:grid-cols-3\">{topic.modes.map(m=><label key={m.key} className=\"text-xs text-gray-800\">{s.modes}: {m.key}<select value={modes[m.key]||m.default} onChange={e=>{setResult(null);setModes(old=>({...old,[m.key]:e.target.value}));}} className=\"mt-1 w-full rounded-lg border border-gray-300 bg-white p-2\">{m.options.map(v=><option key={v}>{v}</option>)}</select></label>)}{topic.parameters.map(p=><label key={p.key} className=\"text-xs text-gray-800\">{p.label} <code>({p.key})</code><input type=\"number\" step=\"any\" min={p.min} max={p.max} value={numbers[p.key]??''} placeholder={String(p.default)} onChange={e=>{setResult(null);setNumbers(old=>({...old,[p.key]:e.target.value}));}} className=\"mt-1 w-full rounded-lg border border-gray-300 bg-white p-2 text-gray-900\" /><span className=\"mt-1 block text-gray-600\">{p.min}–{p.max} {p.unit}</span></label>)}</div></details>}\n <div className=\"mt-3 flex flex-wrap gap-2\">{(topic?[sample]:['Ohm 12 V 6 ohm',\"Newton second law 10 kg 50 N friction2=0\",'Waves f=1 lambda=2','Projectile 30 m/s 45°']).map(text=><button key={text} onClick={()=>{setPrompt(text);void submit(text);}} disabled={busy} className=\"rounded-xl border border-gray-300 bg-white px-3 py-2 text-left text-xs leading-5 text-gray-800\">{text}</button>)}</div>\n {error&&<p role=\"alert\" className=\"mt-3 rounded-xl bg-red-50 p-3 text-sm text-red-900\">{error}</p>}{result&&<ResultCard result={result}/>}<p className=\"mt-4 text-xs leading-6 text-gray-600\">{s.notes}</p></div>;\n}\n", "capstone/ALL_TOPICS_START_HERE.md": "# All-topic explorer and free explainer\n\n## Install\n\nPlace `patch-all-topics-explorer.sh` beside package.json in your existing project. From that folder run:\n\n```bash\nbash patch-all-topics-explorer.sh\nnpm run dev\n```\n\nRestart an already running development server before testing. Open http://localhost:3000/explore or choose **Explore topics** from the header. Deploy the source changes normally to add the explorer to your Vercel site.\n\nThe patch needs the existing project dependencies, including TypeScript, installed in node_modules. It does not install packages, change credentials or deploy anything. It prepares all source changes before writing them, backs up changed files, and retains unrelated edits in simulation pages by inserting only a preset hook and import. If it cannot locate an expected component, it stops before applying the patch. Do not rerun older projectile-only AI patches afterwards; they would replace the new prompt bar and endpoint.\n\n## What is covered\n\n58 distinct activity routes: Physics simulations, Chemistry playgrounds, Mathematics explorers and Geophysics. The legacy Physics unit-circle URL redirects to Mathematics and is not counted twice. Existing Minitab student-login restrictions remain in force. No new Biology simulation is claimed; the /tutor Biology lesson remains separate.\n\nEvery registered activity has a matching overview, key relation/principle, a free local-language concept explanation and an activity link. The original full activity text and technical topic names remain in English. English, Yoruba, Hausa and Igbo are available for the explainer. Formulae, assumptions accompanying computed examples and technical parameter labels remain in English/SI notation. Translations are drafts for fluent subject-teacher review.\n\n47 activities have numeric preset adapters covering 256 source-verified controls. Their available simulation modes are included where a verified mode catalogue exists. Controls without an adapter remain manual inside the original activity. Some activities mix several modes: a field for an inactive mode will not affect the current display. Select the appropriate mode and change its controls. The explorer lists all registered numeric fields; it does not claim every interactive setting is automated.\n\nThe remaining 11 activities open with their original controls and a topic explainer: electrostatic charging, space, compound builder, organic molecules, periodic table, the four Geophysics tools, gamma function and gradient explorer. Composition, atom selection, molecular drawing and iframe-based tools keep their existing interfaces; numerical input is not guessed for these activities.\n\n## Main workflow\n\n1. Select the topic and response language.\n2. Expand **Settings to apply** to inspect the actual field keys, defaults and allowed ranges.\n3. Enter optional values in those fields, or write a supported prompt.\n4. Click **Explain and prepare**. Review the explanation and prepared settings.\n5. Click **Open simulation**. This uses a full page load so the initial settings reach the existing React state reliably.\n6. Use the simulation's normal Run and Reset controls. The explainer does not start or observe the animation.\n\nThe homepage retains its existing projectile quick preview. Non-projectile requests prepare a link to their own page; they do not replace the homepage canvas. Use /explore for a dedicated topic-neutral experience. The explanation panel appears on registered pages, with prepared settings expanded when supplied. If sliders are changed afterwards, the panel remains an explanation of the prepared settings, not a live measurement of the current simulation.\n\n## Example prompts\n\n```\nOhm 12 V 6 ohm\nNewton second law 10 kg 50 N friction2=0\nWaves f=1 lambda=2\nProjectile 30 m/s 45°\nUnit circle 30 degrees\nGas laws law=ideal temperature=300 moles=0.1 volume=4\nRadioactive decay halfLife=5 n0=400\nQuantum tunneling particleEnergy=1 barrierHeight=2 barrierWidth=2\n```\n\nExact `key=value` syntax works for each numeric field listed under the chosen topic. Short natural-language/units forms are available for selected common cases; the parser is not a language model. It does not solve arbitrary questions or generate new simulations. Unrecognised numerical values, invalid ranges and duplicate fields are rejected. Omitted values use the displayed defaults. Supplying a field both in the settings form and the prompt is considered a duplicate.\n\nFor non-standard projectile modes use the exact keys for that mode, such as `mode=horizontal hV0=20 hH=30`, rather than a generic speed shortcut. Parameters for other modes keep their source defaults.\n\n## Calculations\n\nComputed examples are provided for Ohm's law/series/parallel ohmic circuits, Newton's second-law horizontal block model, standard projectile motion, simple travelling-wave speed/period and the unit circle. Other topics show their own principle and existing activity instead of fabricating a numerical answer. Non-ohmic, complex or unsupported submodes do not receive a misleading generic calculation.\n\nFor `Ohm 12 V 6 ohm`, I = 2 A and P = 24 W. For `Newton second law 10 kg 50 N friction2=0`, a = 5 m/s². Without the friction setting, the existing simulation's coefficient 0.2 is used and the explanation includes that friction model.\n\n## File map\n\n- src/lib/explorer/topics-data.json — shared topic catalogue, controls, limits, modes and routes.\n- src/lib/explorer/catalog.ts — catalogue types and lookup.\n- src/lib/explorer/prepare.ts — topic detection, validated settings, preset URLs and selected calculations.\n- src/lib/explorer/locales.ts — language labels and concept explanations.\n- src/lib/explorer/use-topic-preset.ts — initial URL-to-state bridge.\n- src/components/ai/PromptBar.tsx — topic/language selection and prompt input.\n- src/components/explorer/ResultCard.tsx — explanation and prepared settings.\n- src/components/explorer/TopicContext.tsx — activity-page explanation panel.\n- src/app/explore/page.tsx — topic-neutral explorer.\n- src/app/api/ai/route.ts — free all-topic endpoint, with no model-provider calls.\n\nAdding a future activity requires a catalogue entry and, if numeric handoff is wanted, a verified state adapter. New catalogue entries are not created automatically. This patch uses the uploaded source as its inventory.\n\n## Important implementation limits\n\nThe free /api/ai response now uses a topic-aware contract (`topicId`, `params`, `modes`, `url`, `explanation`); the patched prompt bar understands it. Any separately written client that relied on the old six-value `simulationType` response would need updating. The supplied source had only the patched PromptBar as its caller.\n\nThe separate /tutor guided demo and /api/tutor endpoint are unchanged. The former Anthropic simulation parser remains on disk but is not called by the new /api/ai endpoint. SIMULATION_AI_MODE does not enable paid requests through this new free endpoint. All-topic live generative AI would require a separate, deliberate integration later.\n\n## Checks completed and remaining\n\nProduction build and TypeScript checks passed in the supplied project. Automated checks covered all 58 route files, all 232 topic/language combinations, bounds, mode values, URL round trips, topic-name recognition and representative calculations. Endpoint checks used an invalid provider key with external fetch blocked. Preset-hook checks covered all 47 numeric activities and 256 field names. The installer was checked for application, repeat runs and preservation of unrelated source edits.\n\nBrowser visual/interaction QA and fluent-speaker review remain outstanding. The managed preview runner could not launch this Next.js project because it supplied incompatible dev-command flags; no browser-tested claim is made. After installation, try the examples above on your own browser and verify their settings against the activity controls before presenting.\n"};
