  const owners=[];walk(tree,n=>{if(!(ts.isFunctionDeclaration(n)||ts.isFunctionExpression(n)||ts.isArrowFunction(n))||!n.body||!ts.isBlock(n.body))return;const name=n.name?.getText()||n.parent?.name?.getText();if(name===c.owner)owners.push(n);});
  if(owners.length!==1)stop('Cannot uniquely locate '+c.owner+' in '+a.file);
